func sortQuery(query Query, field string) Query {
	query.Page = 1
	if query.Sort != field {
		query.Sort = field
		query.Direction = "asc"
	} else if query.Direction == "asc" {
		query.Direction = "desc"
	} else {
		query.Sort = ""
		query.Direction = ""
	}
	return query
}

